using System.IO.Compression;
using System.Security.Cryptography;
using System.Security.Cryptography.Pkcs;
using System.Security.Cryptography.X509Certificates;
using System.Text.Json;
using MountedGames.Api.Dtos;
using MountedGames.Api.Entities.Apple;
using MountedGames.Api.Entities.Commerce;
namespace MountedGames.Api.Services.Apple;

public sealed class ApplePassIssuer(AppleOptions options, AppleSecrets secrets, TimeProvider clock)
{
    internal static X509Certificate2 LoadCertificate(AppleOptions options) => X509CertificateLoader.LoadPkcs12(
        Convert.FromBase64String(options.Certificate!), options.CertificatePassword, X509KeyStorageFlags.EphemeralKeySet);
    public byte[] Issue(WalletPass pass, ArrivalBookingDto booking)
    {
        if (!options.WalletReady) throw new InvalidOperationException("Apple Wallet is not configured.");
        using var certificate = LoadCertificate(options);
        using var intermediate = X509CertificateLoader.LoadCertificate(Convert.FromBase64String(options.Intermediate!));
        var now = clock.GetUtcNow().UtcDateTime;
        if (!certificate.HasPrivateKey || now < certificate.NotBefore.ToUniversalTime() || now >= certificate.NotAfter.ToUniversalTime()
            || now >= intermediate.NotAfter.ToUniversalTime() || !certificate.Subject.Contains(options.PassTypeId!, StringComparison.Ordinal))
            throw new InvalidOperationException("The Wallet signing certificate needs attention.");
        var stable = booking.Benefits.Where(x => x.Kind == ArrivalFulfilmentKind.Stable && x.Status == "paid").Sum(x => x.Quantity);
        var hookup = booking.Benefits.Where(x => x.Kind == ArrivalFulfilmentKind.Hookup && x.Status == "paid").Sum(x => x.Quantity);
        var allocations = string.Join(" · ", booking.Benefits.SelectMany(x => x.Allocations).Select(x => $"{x.Resource} ({x.Night})"));
        var gate = $"{options.PublicBaseUrl!.TrimEnd('/')}/competitions/{booking.CompetitionId}/entries?arrival={booking.Reference}";
        var document = new Dictionary<string, object?> {
            ["formatVersion"] = 1, ["passTypeIdentifier"] = options.PassTypeId, ["serialNumber"] = pass.Serial,
            ["teamIdentifier"] = options.TeamId, ["organizationName"] = "Mounted Games", ["description"] = "Arrival pass",
            ["logoText"] = "Mounted Games", ["foregroundColor"] = "rgb(255,255,255)", ["backgroundColor"] = "rgb(23,56,95)",
            ["labelColor"] = "rgb(220,230,240)", ["authenticationToken"] = secrets.Unprotect(pass.ProtectedAuthenticationToken, "wallet-auth"),
            ["webServiceURL"] = options.PublicBaseUrl.TrimEnd('/') + "/api/apple/wallet",
            ["relevantDate"] = DateTime.SpecifyKind(booking.StartDate, DateTimeKind.Utc).ToString("O"),
            ["expirationDate"] = DateTime.SpecifyKind((booking.EndDate ?? booking.StartDate).AddDays(1), DateTimeKind.Utc).ToString("O"),
            ["voided"] = booking.Voided || booking.NeedsReview,
            ["barcodes"] = new[] { new { format = "PKBarcodeFormatQR", message = gate, messageEncoding = "iso-8859-1", altText = "Staff check required" } },
            ["generic"] = new {
                primaryFields = new[] { new { key = "event", label = "EVENT", value = booking.CompetitionName } },
                secondaryFields = new[] { new { key = "vehicle", label = "VEHICLE", value = booking.VehicleRegistration.Length == 0 ? "Not recorded" : booking.VehicleRegistration },
                    new { key = "admission", label = "ADMISSION", value = booking.Admission == "paid" ? "Confirmed" : booking.Admission == "pending" ? "Payment pending" : "No admission included" } },
                auxiliaryFields = new[] { new { key = "stable", label = "STABLES", value = stable.ToString() }, new { key = "hookup", label = "HOOK-UPS", value = hookup.ToString() } },
                backFields = new[] { new { key = "allocations", label = "Allocations", value = allocations.Length == 0 ? "Check with the organiser" : allocations },
                    new { key = "verification", label = "Arrival check", value = "Staff must check this pass online. A saved pass may have changed since it was downloaded." },
                    new { key = "venue", label = "Venue", value = booking.Venue ?? "Check the event details" } }
            }
        };
        if (booking.Latitude is >= -90 and <= 90 && booking.Longitude is >= -180 and <= 180)
            document["locations"] = new[] { new { latitude = booking.Latitude, longitude = booking.Longitude, relevantText = booking.CompetitionName } };
        var files = new Dictionary<string, byte[]> { ["pass.json"] = JsonSerializer.SerializeToUtf8Bytes(document), ["icon.png"] = Icon, ["icon@2x.png"] = Icon };
        var manifest = JsonSerializer.SerializeToUtf8Bytes(files.ToDictionary(x => x.Key, x => Convert.ToHexString(SHA1.HashData(x.Value)).ToLowerInvariant()));
        var cms = new SignedCms(new ContentInfo(manifest), detached: true);
        var signer = new CmsSigner(SubjectIdentifierType.IssuerAndSerialNumber, certificate) { IncludeOption = X509IncludeOption.EndCertOnly, DigestAlgorithm = new Oid("2.16.840.1.101.3.4.2.1") };
        signer.Certificates.Add(intermediate); signer.SignedAttributes.Add(new Pkcs9SigningTime(now)); cms.ComputeSignature(signer);
        files["manifest.json"] = manifest; files["signature"] = cms.Encode();
        using var stream = new MemoryStream();
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Create, true))
            foreach (var file in files) { using var output = archive.CreateEntry(file.Key).Open(); output.Write(file.Value); }
        return stream.ToArray();
    }
    private static readonly byte[] Icon = Convert.FromBase64String("");
}
